def solve(payload):
    matrix, vector = payload["A"], payload["b"]
    n = len(matrix)
    if not 1 <= n <= 8 or len(vector) != n or any(len(row) != n for row in matrix):
        return {"error": "shape"}
    augmented = [[float(v) for v in row] + [float(vector[i])] for i, row in enumerate(matrix)]
    for column in range(n):
        pivot = max(range(column, n), key=lambda row: abs(augmented[row][column]))
        if abs(augmented[pivot][column]) <= 1e-12:
            return {"error": "singular"}
        augmented[column], augmented[pivot] = augmented[pivot], augmented[column]
        for row in range(column + 1, n):
            factor = augmented[row][column] / augmented[column][column]
            for j in range(column, n + 1):
                augmented[row][j] -= factor * augmented[column][j]
    result = [0.0] * n
    for row in range(n - 1, -1, -1):
        remainder = sum(augmented[row][j] * result[j] for j in range(row + 1, n))
        result[row] = (augmented[row][n] - remainder) / augmented[row][row]
    return {"solution": result}

